PRAGMA foreign_keys=ON;
CREATE TABLE IF NOT EXISTS libros (id INTEGER PRIMARY KEY AUTOINCREMENT, isbn VARCHAR(255) NOT NULL UNIQUE, titulo VARCHAR(255) NOT NULL, autor VARCHAR(255) NOT NULL, categoria VARCHAR(255) NOT NULL, disponible BOOLEAN NOT NULL DEFAULT 1);
CREATE TABLE IF NOT EXISTS estudiantes (id INTEGER PRIMARY KEY AUTOINCREMENT, dni VARCHAR(255) NOT NULL UNIQUE, nombre VARCHAR(255) NOT NULL, email VARCHAR(255));
CREATE TABLE IF NOT EXISTS prestamos (id INTEGER PRIMARY KEY AUTOINCREMENT, libro_id INTEGER NOT NULL REFERENCES libros(id) ON DELETE RESTRICT, estudiante_id INTEGER NOT NULL REFERENCES estudiantes(id) ON DELETE RESTRICT, inicio DATE NOT NULL, vencimiento DATE NOT NULL, devolucion DATE, multaCentavos BIGINT NOT NULL DEFAULT 0, pagada BOOLEAN NOT NULL DEFAULT 0, CHECK(vencimiento>=inicio), CHECK(devolucion IS NULL OR devolucion>=inicio));
CREATE UNIQUE INDEX IF NOT EXISTS un_prestamo_activo_por_libro ON prestamos(libro_id) WHERE devolucion IS NULL;
